import hashlib,json,os
from pathlib import Path
mp=Path(os.environ['STAMPED_DELIVERY_MANIFEST']); m=json.loads(mp.read_text()); root=Path(os.environ['STAMPED_JUDGE_TARGET']); errors=[]; checked=0
for row in m['entries']:
 if not row['path'].startswith('content/workspace/'): continue
 p=root/Path(row['path']).relative_to('content/workspace'); checked+=1; kind=row['kind']
 if kind=='file':
  if not p.is_file() or hashlib.sha256(p.read_bytes()).hexdigest()!=row['sha256']: errors.append({'path':row['path'],'issue':'missing or SHA-256 mismatch'})
 elif kind=='symlink':
  actual=os.readlink(p) if p.is_symlink() else None
  if actual!=row.get('link_target'): errors.append({'path':row['path'],'issue':'missing or link target mismatch'})
  elif hashlib.sha256(actual.encode()).hexdigest()!=row['sha256']: errors.append({'path':row['path'],'issue':'symlink SHA-256 mismatch'})
 elif kind=='directory' and not p.is_dir(): errors.append({'path':row['path'],'issue':'missing directory'})
print(json.dumps({'capture_status':m['capture_status'],'capture_sha256':hashlib.sha256(mp.read_bytes()).hexdigest(),'declared_capture_sha256':json.loads(Path(os.environ['STAMPED_WORKER_STOP_RECEIPT']).read_text())['capture']['sha256'],'workspace_entries_checked':checked,'mismatches':errors,'manifest_errors':m.get('errors',[]),'manifest_omissions':m.get('omissions',[])},indent=2))
PY
cat "$STAMPED_JUDGE_OUTPUT/delivery-verification.json"","max_output_tokens":1500});
text(r.output);

